using namespace rpg;using namespace rpg::presentation;
void check(bool ok,const char* text){if(!ok){throw std::runtime_error(text);}}
struct MemoryFiles:storage::Files {std::map<std::string,std::string> files;bool fail=false;bool ensure_directory()override{return true;}storage::ReadResult read(std::string_view key,std::size_t limit)override{const auto it=files.find(std::string(key));if(it==files.end()){return {};}return it->second.size()>limit?storage::ReadResult{storage::ReadState::Failed,{}}:storage::ReadResult{storage::ReadState::Ready,it->second};}bool copy(std::string_view,std::string_view)override{return false;}bool write(std::string_view key,std::string_view bytes)override{files[std::string(key)]=std::string(bytes);return true;}bool replace(std::string_view target,std::string_view temporary)override{if(fail){return false;}files[std::string(target)]=files[std::string(temporary)];files.erase(std::string(temporary));return true;}void discard(std::string_view)override{}};
int main(){try{
 ClassicSearchSession classic;check(classic.act(0,SearchAction::Reconnaissance),"search action");check(classic.state().search==25&&classic.state().storm==15,"settings");const auto before=classic.state();check(!classic.act(0,SearchAction::Advance)&&classic.state()==before,"stale no mutation");check(classic.act(1,SearchAction::Reconnaissance)&&classic.state().dialogue,"threshold dialogue");const auto paused=classic.state();check(!classic.act(2,SearchAction::Advance)&&classic.state()==paused,"dialogue pauses actions");check(classic.acknowledge()&&classic.state().storm==30,"dialogue no advance");check(classic.act(2,SearchAction::Concentrate)&&classic.act(3,SearchAction::Reconnaissance)&&classic.state().outcome==SearchOutcome::Recovered,"recover");
 classic.reset();check(classic.state().attempt==2&&classic.state().search==0&&!classic.state().dialogue_seen,"reset");classic.abandon();check(classic.state().outcome==SearchOutcome::Abandoned&&!classic.act(classic.state().revision,SearchAction::Advance),"abandon terminal");
 ClassicSearchSession storm;for(int i=0;i<7;++i){check(storm.act(storm.state().revision,SearchAction::Concentrate),"storm action");}check(storm.state().outcome==SearchOutcome::Storm&&storm.state().search==0,"no stacking concentration storm");
 ClassicSearchSession simultaneous({100,25,100,20,200});check(simultaneous.act(0,SearchAction::Reconnaissance)&&simultaneous.state().outcome==SearchOutcome::Recovered,"search beats storm");ClassicSearchSession limit({25,25,15,20,1});check(limit.act(0,SearchAction::Advance)&&limit.state().outcome==SearchOutcome::ActionLimit,"action ceiling");
 check(hub_uppercase("Praça, missões, preparação e ação") == "PRAÇA, MISSÕES, PREPARAÇÃO E AÇÃO","UTF8 uppercase accents");
 const auto definition=standard_tutorial_definition();check(definition.stage.encounters.size()==2&&definition.stage.squad[0].id=="CHAR_FELIPE_JOVEM"&&definition.stage.squad[0].stats.defense==950,"young fixture");
 TutorialSession tutorial;const auto initial=tutorial.state();check(tutorial.awaiting_lesson()&&!tutorial.submit(0,1,"MOB_TEMPESTADE_01").accepted()&&tutorial.state().revision==0,"intro gating");tutorial.acknowledge();check(!tutorial.submit(0,3,"MOB_TEMPESTADE_01").accepted()&&tutorial.state().revision==0,"first lesson requires basic A1");check(has_status(*std::ranges::find(initial.combat.battle.fighters,std::string("MOB_TEMPESTADE_01"),[](const Fighter& f){return f.definition.id;}),EffectKind::Bleed),"initial bleed");
 int accepted=0;bool saw_second=false;for(int i=0;i<400&&!tutorial.finished();++i){if(tutorial.awaiting_lesson()){const auto rev=tutorial.state().revision;tutorial.acknowledge();check(tutorial.state().revision==rev,"lesson no turn");}const auto s=tutorial.state();VisualResult result;if(s.automatic){result=tutorial.step_automatic();}else{auto targets=tutorial.allowed_slot(3)?target_candidates(s,3):std::vector<std::string>{};std::uint32_t slot=3;if(targets.empty()){targets=target_candidates(s,1);slot=1;}check(!targets.empty(),"tutorial target");result=tutorial.submit(s.revision,slot,targets.back());}check(result.accepted(),"tutorial accepted step");++accepted;saw_second|=tutorial.wave_index()==1;}
 check(tutorial.finished()&&accepted>0&&saw_second&&tutorial.hud().objective_met,"two waves can be won with current kit");tutorial.reset();check(tutorial.state().revision>initial.revision&&tutorial.awaiting_lesson()&&tutorial.wave_index()==0,"tutorial reset intro");
 auto setup=felipe_pilot_setup();Status attack{EffectKind::AttackUp,2,TickPolicy::NaturalOnly,0,2000};Status slow{EffectKind::SpeedDown,2,TickPolicy::NaturalOnly,0,1500};Battle stats(setup.roster,setup.rules,{},{{"FELIPE",110,{attack,slow},{{"FELIPE-A1",0},{"FELIPE-A3",0}}}});check(effective_attack(*stats.find("FELIPE"))==3000&&action_speed(*stats.find("FELIPE"))==93,"effective stat floor");check(stats.find("FELIPE")->definition.attack==2500&&stats.find("FELIPE")->effective_speed==110,"base unchanged");
 // Timed effects use the same expiry/renewal and dispel pipeline as other common states.
 auto timed=felipe_pilot_setup();for(auto& unit:timed.roster){unit.max_health=100000;unit.attack=100;unit.stats.block=0;}
 timed.rules.skills.push_back({"BOOST","FELIPE",0,TargetRule::Self,{{EffectKind::AttackUp,2000,2}}});
 Battle renewal(timed.roster,timed.rules);check(renewal.apply({"FELIPE",ActionType::Skill,"FELIPE","BOOST"}).accepted(),"apply attack buff");
 const auto buffCount=[](const Fighter& unit){return std::ranges::count(unit.statuses,EffectKind::AttackUp,&Status::kind);};check(effective_attack(*renewal.find("FELIPE"))==120&&buffCount(*renewal.find("FELIPE"))==1,"buff nonstack");
 for(int i=0;i<20 && renewal.current_actor()->definition.id!="FELIPE";++i){check(renewal.apply(*choose_basic_attack(renewal)).accepted(),"enemy advance");}
 check(renewal.apply({"FELIPE",ActionType::Skill,"FELIPE","BOOST"}).accepted()&&buffCount(*renewal.find("FELIPE"))==1,"reapply refresh not stack");
 int own=0;for(int i=0;i<20&&own<2;++i){const auto* unit=renewal.current_actor();if(unit->definition.id=="FELIPE"){++own;}check(renewal.apply(*choose_basic_attack(renewal)).accepted(),"expiry progression");}check(!has_status(*renewal.find("FELIPE"),EffectKind::AttackUp)&&effective_attack(*renewal.find("FELIPE"))==100,"expires after two natural opportunities");
 ClassicSearchSession nonstack;check(nonstack.act(0,SearchAction::Concentrate)&&nonstack.act(1,SearchAction::Concentrate)&&nonstack.act(2,SearchAction::Reconnaissance)&&nonstack.state().search==50,"concentration explicit nonstack");
 bool invalid=false;try{auto bad=definition;bad.stage.encounters[0].initial_runtime[0].id="CHAR_FELIPE_JOVEM";WaveVisualSession reject(bad);}catch(const std::invalid_argument&){invalid=true;}check(invalid,"enemy preparation cannot override allied carry");
 MemoryFiles files;storage::Keys keys{"tutorial.txt","tutorial.pending",{}, {}};check(load_tutorial_completion(files,keys)==TutorialCompletion{},"missing completion default");check(record_tutorial_completion(files,keys,false)==TutorialCompletion{true,false},"standard completion");check(record_tutorial_completion(files,keys,true)==TutorialCompletion{true,true},"both flags preserved");const auto saved=files.files["tutorial.txt"];files.fail=true;bool failed=false;try{record_tutorial_completion(files,keys,true);}catch(const SaveError&){failed=true;}check(failed&&files.files["tutorial.txt"]==saved,"failed commit preserves completion");files.files["tutorial.txt"]="invalid";failed=false;try{record_tutorial_completion(files,keys,false);}catch(const SaveError&){failed=true;}check(failed&&files.files["tutorial.txt"]=="invalid","invalid record preserved");
 std::cout<<"REG_TUTORIAL_TESTS_RESULT passed=18 total=18\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
